arguments.new_str:
@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Shipment Tracker</h1>

<p>Welcome to the logistics shipment tracking system.</p>

<AuthorizeView>
    <Authorized>
        <p>You are logged in as <strong>@context.User.Identity?.Name</strong>.</p>
        <p><a href="shipments" class="btn btn-primary">View All Shipments</a></p>
    </Authorized>
    <NotAuthorized>
        <p>Track your shipment using a tracking number, or log in to access the full dashboard.</p>
    </NotAuthorized>
</AuthorizeView>

<hr />

<h3>Track a Shipment</h3>
<div class="row">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001-2026)"
                   @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-outline-secondary" @onclick="TrackShipment">Track</button>
        </div>
    </div>
</div>

@if (searched)
{
    <div class="mt-3">
        @if (trackedShipment is not null)
        {
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Shipment @trackedShipment.TrackingNumber</h5>
                    <p><strong>Status:</strong> <span class="badge bg-@GetStatusColor(trackedShipment.Status)">@trackedShipment.Status</span></p>
                    <p><strong>Origin:</strong> @trackedShipment.Origin</p>
                    <p><strong>Destination:</strong> @trackedShipment.Destination</p>
                    <p><strong>Estimated Delivery:</strong> @(trackedShipment.EstimatedDelivery?.ToString("MMMM dd, yyyy") ?? "TBD")</p>
                </div>
            </div>
        }
        else
        {
            <div class="alert alert-warning">No shipment found with tracking number "<strong>@searchedNumber</strong>".</div>
        }
    </div>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private Shipment? trackedShipment;
    private bool searched;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searchedNumber = trackingNumber.Trim();
        trackedShipment = await ShipmentService.GetByTrackingNumberAsync(searchedNumber);
        searched = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

