using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> Shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, EstimatedDelivery = new DateTime(2026, 6, 18), CustomerEmail = "alice@example.com", CreatedAt = new DateTime(2026, 6, 10) },
        new Shipment { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.OutForDelivery, EstimatedDelivery = new DateTime(2026, 6, 15), CustomerEmail = "bob@example.com", CreatedAt = new DateTime(2026, 6, 8) },
        new Shipment { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.Pending, EstimatedDelivery = new DateTime(2026, 6, 25), CustomerEmail = "carol@example.com", CreatedAt = new DateTime(2026, 6, 13) },
        new Shipment { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.Delivered, EstimatedDelivery = new DateTime(2026, 6, 12), CustomerEmail = "dave@example.com", CreatedAt = new DateTime(2026, 6, 5) },
        new Shipment { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "São Paulo, BR", Destination = "Paris, FR", Status = ShipmentStatus.Delayed, EstimatedDelivery = new DateTime(2026, 6, 20), CustomerEmail = "eve@example.com", CreatedAt = new DateTime(2026, 6, 11) },
    };

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return Task.FromResult(Shipments.OrderByDescending(s => s.CreatedAt).ToList());
    }

    public Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = Shipments.FirstOrDefault(s =>
            s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(shipment);
    }

    public Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = Shipments.FirstOrDefault(s => s.Id == id);
        if (shipment is not null)
        {
            shipment.Status = newStatus;
        }
        return Task.CompletedTask;
    }
}
EOF

